CREATE TABLE assistant_operations (
 id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id),
 client_request_id TEXT NOT NULL, local_session_id TEXT NOT NULL,
 turn_id TEXT NOT NULL, step_id TEXT NOT NULL,
