CREATE INDEX idx_team_assets_team_created
    ON team_assets(team_id, created_at DESC);
CREATE INDEX idx_assistant_queued ON assistant_operations(state,created_at);
CREATE UNIQUE INDEX idx_assistant_active_budget ON assistant_turn_budgets(user_id) WHERE state='active';
